float hash( float n ) {
	return fract(sin(n)*43758.5453);
}

float noise( in vec3 x ) {
	vec3 p = floor(x);
	vec3 f = fract(x);

	f = f*f*(3.0-2.0*f);
	float n = p.x + p.y*57.0 + 113.0*p.z;
	return mix(mix(mix( hash(n+  0.0), hash(n+  1.0),f.x),
				   mix( hash(n+ 57.0), hash(n+ 58.0),f.x),f.y),
			   mix(mix( hash(n+113.0), hash(n+114.0),f.x),
				   mix( hash(n+170.0), hash(n+171.0),f.x),f.y),f.z);
}

float fbm( vec3 p ) {
    float f = 0.0;
    f += 0.5000 * noise(p); p *= 2.02;
    f += 0.2500 * noise(p); p *= 2.03;
    f += 0.1250 * noise(p); p *= 2.01;
    f += 0.0625 * noise(p); p *= 2.04;
    f /= 0.9375;
    return f;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = 2.0 * ((fragCoord.xy / iResolution.xy) - 0.5);

    uv.y *= iResolution.y / iResolution.x;
    vec2 uv2 = uv;

    float fi = fbm(vec3(uv.yx, iTime / 10.0 + 3.0));
    uv += (fi - 0.5) / 4.0;
    float fi2 = fbm(vec3(uv.yx * vec2(1.0, 0.5 - (uv2.y + 2.0)) / 4.0, iTime / 30.0 + 10.0));
    uv += (fi2 - 0.5) / 8.0;

    float f = fbm(vec3(uv * 8. - vec2(0.0, iTime * 4.0) , iTime / 3.0 + 2.0));

    vec3 color = vec3(f) * vec3(1.0, 0.5, 0.0) * (1.7 - (uv2.y / (uv2.y + 1.5))  * 5.0);

	fragColor = vec4(color, 1.0);
}
